{"command":"F=/tmp/claude-0/-home-user-deepseek-harness/302448e7-0723-4bbe-8694-8354274362da/scratchpad/npm-audit.json
node -e '
const d = require(process.argv[1]);
const vulns = d.vulnerabilities;
function show(name, depth=0, seen=new Set()) {
  if (seen.has(name)) return;
  seen.add(name);
  const v = vulns[name];
  if (!v) return;
  const own = v.via.filter(x=>typeof x==="object");
  const deps = v.via.filter(x=>typeof x==="string");
  console.log(" ".repeat(depth*2)+"- "+name+" severity="+v.severity);
  for (const a of own) console.log(" ".repeat(depth*2+2)+"ADVISORY: "+a.title+" ("+a.url+") sev="+a.severity+" cwe="+JSON.stringify(a.cwe));
  for (const dep of deps) show(dep, depth+1, seen);
}
show("helmet");
console.log("----forever----");
show("forever");
' "$F"
","description":"Trace advisory chains for helmet and forever"}

